head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) {
    return createElementNS(XHTML_NS, tagName, options);
  };
})();

body.script:
(function(){
  if(!("serviceWorker" in navigator)) {
    console.warn("[single] no SW support");
    return;
  }
  const b64 = "";
  function b64ToUint8(b64) {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
  }
  try {
    const code = new TextDecoder().decode(b64ToUint8(b64));
    const blob = new Blob([code], {type: "application/javascript"});
    const url = URL.createObjectURL(blob);
    navigator.serviceWorker.register(url, {scope: "./"}).then(reg => {
      console.log("[single] SW registered", reg.scope);
      if (reg.waiting) reg.waiting.postMessage({type:"SKIP_WAITING"});
      if (reg.active) {
        reg.active.postMessage({type:"CLAIM"});
      }
      // force claim
      navigator.serviceWorker.ready.then(r => {
        if (r.active) r.active.postMessage({type:"CLAIM"});
      });
    }).catch(e => console.warn("[single] SW register failed", e));
  } catch(e) {
    console.warn("[single] SW create failed", e);
  }
})();
